def send_email(send_email_info, get_email_info, smtp_code, info, path, subject):
    from_addr = send_email_info
    password = smtp_code
    to_addrs = get_email_info
    smtp_server = QQ_SERVER
    local_time = time.strftime('%Y-%m-%d %H:%M:%S')
    content = f'{{{info!s}}}邮件发送时间:{{{local_time!s}}}'
    msg = MIMEMultipart()
    body = MIMEText(content.encode(), 'plain', 'utf-8')
    msg.attach(body)
    if path and EMAIL_FILE_PERMISSION == '1':
        path = ''
        strategy_log.error('系统配置不允许发送邮件附件, 本次发送过程附件将不会被发送')
    if path:
        size = os.path.getsize(path)
        size = float(round(size / 1024 / 1024, 2))
        if size >= float(EMAIL_FILE_SIZE_LIMIT):
            strategy_log.error(f'send_email上传文件大小为：{size!s}MB,超过系统配置限制：{EMAIL_FILE_SIZE_LIMIT!s}MB')
            return None
        else:
            try:
                attachment = MIMEBase('application', 'octet-stream')
                attachment.set_payload(open(path, 'rb').read())
                encoders.encode_base64(attachment)
                attachment.add_header('Content-Disposition', 'attachment', filename=path.split('/')[-1])
                msg.attach(attachment)
            except BaseException as e:
                from io import StringIO
                import traceback
                error_message = StringIO()
                traceback.print_exc(file=error_message)
                error_message = str(error_message.getvalue())
                strategy_log.error('邮箱消息推送过程文件解析失败，原因：%s' % error_message)
                return None
            def _format_addr(s):
                name, addr = parseaddr(s)
                return formataddr((Header(name, 'utf-8').encode(), addr))
            msg['From'] = _format_addr('<%s>' % from_addr)
            msg['To'] = _format_addr('<%s>' % to_addrs)
            msg['Subject'] = Header(subject, 'utf-8').encode()
            try:
                server = smtplib.SMTP_SSL(host=smtp_server, port=465)
                server.login(from_addr, password)
                server.sendmail(from_addr, to_addrs=to_addrs, msg=msg.as_string())
                strategy_log.info('邮箱消息推送成功')
                server.quit()
            except BaseException as e:
                from io import StringIO
                import traceback
                error_message = StringIO()
                traceback.print_exc(file=error_message)
                error_message = str(error_message.getvalue())
                strategy_log.error('邮箱消息推送失败，原因：%s' % error_message)
                return None
